 <?= $icon ?>"></i></span><div><strong class="small"><?= $label ?> · <?= sanitize($a['judul']) ?></strong><small class="text-muted d-block"><?= sanitize($a['nama_mapel']) ?> · <?= sanitize($a['nama_kelas']) ?> · <?= date('d/m/Y H:i',strtotime($a['waktu'])) ?></small></div></div><?php endforeach ?><?php if(!$aktivitas_detail): ?><p class="text-muted">Tidak ada aktivitas pada periode ini.</p><?php endif ?></div></div></div></section><?php endif ?>
