<?php foreach($laporan as $r): ?><tr><td class="ps-4"><strong><?= sanitize($r['nama_lengkap']) ?></strong><br><small class="text-muted">NIP <?= sanitize($r['nip']?:'-') ?></small></td><td><?= (int)$r['materi'] ?></td><td><?= (int)$r['tugas'] ?></td><td><?= (int)$r['ujian'] ?></td><td><?= (int)$r['absensi'] ?></td><td><strong class="text-primary"><?= (int)$r['total_konten'] ?></strong></td><td><strong><?= (int)$r['nilai_tugas'] ?>/<?= (int)$r['pengumpulan'] ?></strong><br><small><?= number_format($r['progres_tugas'],1,',','.') ?>%</small></td><td><strong><?= (int)$r['nilai_esai'] ?>/<?= (int)$r['esai_jawaban'] ?></strong><br><small><?= number_format($r['progres_esai'],1,',','.') ?>%</small></td><td><a href="?<?= http_build_query(array_merge($query_state,['guru_id'=>(int)$r['id']])) ?>#detailAktivitas" class="btn btn-sm btn-primary"><i class="fa-solid fa-eye me-1"></i>Detail</a></td></tr><?php endforeach ?><?php if(!$laporan): ?><tr><td colspan="9" class="text-center text-muted py-5">Tidak ada guru sesuai filter.</td></tr><?php endif ?></tbody></table></div><div class="alert alert-light border-0 border-top rounded-0 mb-0 small text-muted"><i class="fa-solid fa-circle-info me-1"></i>Karena sistem belum menyimpan waktu pemberian nilai, filter periode penilaian memakai waktu pengumpulan tugas dan waktu sesi ujian terkait.</div></div></section>
